package com.mutang.xunxi;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.*;
import android.widget.*;
import android.view.*;
import org.jsoup.nodes.Entities;

public final class ReaderActivity extends Activity {
    WebView web;ProgressBar progress;TextView title,status;Button mode;String original,heading;boolean active=true,website=false,webFailed=false,authenticated=false;ArticleReader.Result extracted;
    int d(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);original=getIntent().getStringExtra("url");heading=getIntent().getStringExtra("title");authenticated=getIntent().getBooleanExtra("authenticated",false);if(!ArticleReader.webUrl(original)){finish();return;}
        getWindow().setStatusBarColor(MainActivity.BG);getWindow().setNavigationBarColor(MainActivity.CARD);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(MainActivity.BG);root.setOnApplyWindowInsetsListener((v,i)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(d(8),d(8),d(8),d(8));Button back=new Button(this);back.setText("‹ 返回");back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(-2,-2));title=new TextView(this);title.setText("阅读");title.setTextColor(MainActivity.TEXT);title.setTextSize(18);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setGravity(Gravity.CENTER);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));mode=new Button(this);mode.setText("互动/网页");mode.setOnClickListener(v->{if(website&&extracted!=null)show(extracted);else webPage(original);});bar.addView(mode,new LinearLayout.LayoutParams(-2,-2));Button source=new Button(this);source.setText("↗");source.setContentDescription("在外部浏览器打开原文");source.setOnClickListener(v->external(website&&web!=null&&ArticleReader.webUrl(web.getUrl())?web.getUrl():original,false));bar.addView(source,new LinearLayout.LayoutParams(d(48),-2));root.addView(bar);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);root.addView(progress,new LinearLayout.LayoutParams(-1,d(3)));
        status=new TextView(this);status.setText("正在提取正文…");status.setTextSize(14);status.setTextColor(MainActivity.MUTED);status.setGravity(Gravity.CENTER);status.setPadding(d(16),d(16),d(16),d(16));root.addView(status,new LinearLayout.LayoutParams(-1,-2));web=new WebView(this);web.setBackgroundColor(MainActivity.BG);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setDomStorageEnabled(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(android.os.Build.VERSION.SDK_INT>=26)settings.setSafeBrowsingEnabled(true);settings.setBuiltInZoomControls(true);settings.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
        root.addView(web,new LinearLayout.LayoutParams(-1,0,1));
        if(authenticated){webPage(original);return;}if(ArticleReader.pdfUrl(original)){openPdf(original);finish();return;}
        new Thread(()->{try{ArticleReader.Result result=ArticleReader.read(original);runOnUiThread(()->{if(!active||isFinishing())return;extracted=result;if(!website)show(result);else mode.setText("纯净阅读");});}catch(Exception e){runOnUiThread(()->{if(active&&!isFinishing()&&!website)webPage(original);});}},"xunji-reader").start();}
    void replaceWeb(boolean interactive){android.view.ViewGroup parent=(android.view.ViewGroup)web.getParent();int index=parent.indexOfChild(web);ViewGroup.LayoutParams lp=web.getLayoutParams();parent.removeView(web);web.stopLoading();web.destroy();web=new WebView(this);web.setBackgroundColor(MainActivity.BG);WebSettings s=web.getSettings();s.setJavaScriptEnabled(interactive);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setDomStorageEnabled(interactive);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setSupportMultipleWindows(false);if(android.os.Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);parent.addView(web,index,lp);}
    void webPage(String url){if(!ArticleReader.webUrl(url))return;website=true;webFailed=false;title.setText("网页互动");mode.setText(extracted==null?"刷新网页":"纯净阅读");progress.setVisibility(View.VISIBLE);progress.setIndeterminate(true);status.setVisibility(View.VISIBLE);status.setText("原网站的点赞、评论和登录功能由网站自身提供");replaceWeb(true);WebView v=web;
        v.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String u=request.getUrl().toString();if(!authenticated&&request.isForMainFrame()&&ArticleReader.pdfUrl(u)){openPdf(u);return true;}return !ArticleReader.webUrl(u)||(authenticated&&!u.startsWith("https://"));}@Override public void onPageFinished(WebView view,String u){if(web==view){progress.setVisibility(View.GONE);if(!webFailed)status.setVisibility(View.GONE);}}@Override public void onReceivedError(WebView view,WebResourceRequest req,WebResourceError error){if(web==view&&req.isForMainFrame())fail("网页加载失败，可重试或点击右上角 ↗ 打开原文。");}@Override public void onReceivedHttpError(WebView view,WebResourceRequest req,WebResourceResponse error){if(web==view&&req.isForMainFrame())fail("网站返回 HTTP "+error.getStatusCode()+"；可重试或打开原文。");}});v.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView view,int p){if(web==view){progress.setIndeterminate(false);progress.setProgress(p);if(p==100)progress.setVisibility(View.GONE);}}});v.setDownloadListener((u,a,c,m,l)->{if(authenticated){Toast.makeText(this,"登录站点的附件请使用原网站提供的预览。",Toast.LENGTH_LONG).show();return;}if(ArticleReader.webUrl(u)&&(ArticleReader.pdfUrl(u)||"application/pdf".equalsIgnoreCase(m))){openPdf(u);return;}if(ArticleReader.webUrl(u))new android.app.AlertDialog.Builder(this).setTitle("打开附件").setMessage("此附件需要系统浏览器下载。是否继续？").setNegativeButton("取消",null).setPositiveButton("打开",(d,w)->external(u,false)).show();});v.loadUrl(url);}
    void fail(String message){webFailed=true;progress.setVisibility(View.GONE);status.setVisibility(View.VISIBLE);status.setText(message);}
    void show(ArticleReader.Result r){website=false;title.setText("阅读");mode.setText("互动/网页");replaceWeb(false);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(request.isForMainFrame()&&request.hasGesture()&&ArticleReader.webUrl(request.getUrl().toString())){String u=request.getUrl().toString();if(ArticleReader.pdfUrl(u))openPdf(u);else webPage(u);}return true;}});String name=heading==null||heading.trim().isEmpty()?r.title:heading;String safeTitle=Entities.escape(name==null?"":name);String host=Entities.escape(Collector.host(r.url));String html="<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src https: http:; style-src 'unsafe-inline';\"><style>body{background:#f5f7f4;color:#172e29;font-family:sans-serif;font-size:17px;line-height:1.9;padding:18px;overflow-wrap:anywhere;margin:0}h1{font-size:25px;line-height:1.35;margin:10px 0}h2,h3{line-height:1.45}p{margin:0 0 1em}img{max-width:100%;height:auto;border-radius:8px}a{color:#24745f}blockquote{border-left:3px solid #24745f;padding-left:12px;margin-left:0;color:#52645a}pre{white-space:pre-wrap;background:#e1efe7;padding:12px;border-radius:8px}table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%}td,th{border:1px solid #bdccc1;padding:8px}small{color:#64756e}hr{border:0;border-top:1px solid #d5e0d8}</style></head><body><h1>"+safeTitle+"</h1><small>"+host+" · 应用内阅读</small><hr>"+r.html+"</body></html>";web.loadDataWithBaseURL(r.url,html,"text/html","UTF-8",null);progress.setVisibility(View.GONE);status.setVisibility(View.GONE);}
    void openPdf(String url){startActivity(new Intent(this,PdfActivity.class).putExtra("url",url));}
    void external(String url,boolean close){if(!ArticleReader.webUrl(url))return;try{if(close)Toast.makeText(this,"无法在应用内读取，已打开原文",Toast.LENGTH_SHORT).show();startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));if(close)finish();}catch(Exception e){status.setVisibility(View.VISIBLE);status.setText("无法打开原文，请检查是否已安装浏览器。");}}
    @Override public void onBackPressed(){if(website&&web!=null&&web.canGoBack()){web.goBack();return;}if(website&&extracted!=null){show(extracted);return;}super.onBackPressed();}
    @Override protected void onDestroy(){active=false;if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
